def calc(expr):
    toks, i = [], 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            toks.append(int(expr[i:j]))
            i = j
            continue
        if c in '+-*/()':
            toks.append(c)
        i += 1
    pos = [0]
    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None
    def eat():
        pos[0] += 1
        return toks[pos[0] - 1]
    def atom():
        t = eat()
        if t == '(':
            v = expr_()
            eat()
            return v
        if t == '-':
            return -atom()
        return t
    def term():
        v = atom()
        while peek() in ('*', '/'):
            v = v * atom() if eat() == '*' else v / atom()
        return v
    def expr_():
        v = term()
        while peek() in ('+', '-'):
            v = v + term() if eat() == '+' else v - term()
        return v
    return expr_()
